#if os(iOS)
import SwiftUI
import StrandDesign

/// Renders one `LocalCoachCard` as a bounded, widget-style surface inside a Coach answer. Every figure
/// is read from the card payload; nothing here is generated by the language model. Missing values draw
/// as an em dash, never as zero.
struct LocalCoachCardView: View {
    let card: LocalCoachCard
    @AppStorage(UnitPrefs.effortScaleKey) private var effortScaleRaw = EffortScale.whoop.rawValue
    private var effortScale: EffortScale { UnitPrefs.resolveEffortScale(effortScaleRaw) }

    var body: some View {
        content
            .accessibilityElement(children: .combine)
            .accessibilityLabel(Text(accessibilityText))
            .accessibilityIdentifier("coach.card.\(card.kind)")
    }

    @ViewBuilder private var content: some View {
        switch card {
        case .recovery(let value): CoachRecoveryCard(card: value)
        case .sleep(let value): CoachSleepCard(card: value)
        case .trend(let value): CoachTrendCard(card: value, effortScale: effortScale)
        case .effort(let value): CoachEffortCard(card: value, effortScale: effortScale)
        case .workouts(let value): CoachWorkoutsCard(card: value, effortScale: effortScale)
        case .stats(let value): CoachStatsCard(card: value)
        }
    }

    /// One spoken sentence per card, on the same display scale the card shows.
    private var accessibilityText: String {
        let date = card.day.map { LocalCoachCardFormat.dayLabel($0) } ?? ""
        let stale = card.isStale ? ", stale" : ""
        switch card {
        case .recovery(let value):
            return "Recovery, \(date)\(stale). Score \(LocalCoachCardFormat.whole(value.score, unit: "out of 100")), HRV \(LocalCoachCardFormat.whole(value.hrvMs, unit: "milliseconds")), resting heart rate \(LocalCoachCardFormat.whole(value.restingHr, unit: "beats per minute")), sleep \(LocalCoachCardFormat.duration(minutes: value.sleepMinutes))."
        case .sleep(let value):
            return "Sleep, \(date)\(stale). Total \(LocalCoachCardFormat.duration(minutes: value.totalMinutes)), deep \(LocalCoachCardFormat.duration(minutes: value.deepMinutes)), REM \(LocalCoachCardFormat.duration(minutes: value.remMinutes)), light \(LocalCoachCardFormat.duration(minutes: value.lightMinutes)), efficiency \(LocalCoachCardFormat.whole(value.efficiencyPercent, unit: "percent"))."
        case .trend(let value):
            let format = CoachTrendFormat(metricID: value.metricID, effortScale: effortScale)
            return "\(value.title) trend, newest \(date)\(stale). Latest \(format.text(value.latest)) \(format.unit(value.unit)), average \(format.text(value.average)), low \(format.text(value.minimum)), high \(format.text(value.maximum)), \(value.points.count) observed days."
        case .effort(let value):
            let scaled = value.value.map { UnitFormatter.effortDisplay($0, scale: effortScale) } ?? "not recorded"
            return "Effort, \(date)\(stale). \(scaled) out of \(UnitFormatter.effortScaleMax(effortScale)). \(value.workoutCount.map { "\($0) workouts in \(value.windowDays) days" } ?? "Workout count not available")."
        case .workouts(let value):
            let rows = value.items.map { "\($0.sport), \(LocalCoachCardFormat.startLabel($0.startTs)), \(LocalCoachCardFormat.duration(seconds: $0.durationS))" }
            return "Recent workouts, newest \(date). " + rows.joined(separator: "; ") + "."
        case .stats(let value):
            return "\(value.title), \(date)\(stale). " + value.items.map { "\($0.label) \(LocalCoachCardFormat.displayValue($0.value))" }.joined(separator: ", ") + "."
        }
    }
}

// MARK: - Shared chrome

/// Bounded widget surface: tinted icon + eyebrow title on the left, the record's actual date (and a Stale
/// pill when the newest record is two or more days older than the window that was read) on the right.
private struct CoachCardChrome<Content: View>: View {
    let symbol: String
    let title: String
    let tint: Color
    let dateLabel: String?
    let isStale: Bool
    @ViewBuilder let content: () -> Content

    var body: some View {
        VStack(alignment: .leading, spacing: NoopMetrics.space3) {
            HStack(spacing: NoopMetrics.space2) {
                Image(systemName: symbol).font(StrandFont.caption).foregroundStyle(tint)
                Text(title).strandOverline().lineLimit(1)
                Spacer(minLength: NoopMetrics.space2)
                if isStale { StatePill("Stale", tone: .warning, showsDot: false) }
                if let dateLabel {
                    Text(dateLabel)
                        .font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary).lineLimit(1)
                }
            }
            content()
        }
        .padding(NoopMetrics.cardPadding)
        .frame(maxWidth: .infinity, alignment: .leading)
        .frostedCardSurface(tint: tint, cornerRadius: NoopMetrics.radius4)
    }
}

/// Icon, label and a right-aligned tabular value. Missing values read "—" in the tertiary ink.
private struct CoachMetricRow: View {
    let symbol: String
    let tint: Color
    let label: String
    let value: String
    var unit: String? = nil

    var body: some View {
        HStack(alignment: .firstTextBaseline, spacing: NoopMetrics.space2) {
            Image(systemName: symbol).font(StrandFont.caption).foregroundStyle(tint).frame(width: 18)
            Text(label).font(StrandFont.caption).foregroundStyle(StrandPalette.textSecondary).lineLimit(1)
            Spacer(minLength: NoopMetrics.space1)
            HStack(alignment: .firstTextBaseline, spacing: 2) {
                Text(value).font(StrandFont.bodyNumber)
                    .foregroundStyle(value == "—" ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                if let unit, value != "—" {
                    Text(unit).font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                }
            }
            .lineLimit(1)
        }
    }
}

/// Track-only ring for a gauge whose value was not recorded.
private struct CoachEmptyRing: View {
    let diameter: CGFloat
    let lineWidth: CGFloat

    var body: some View {
        ZStack {
            Circle().stroke(StrandPalette.surfaceInset, lineWidth: lineWidth)
            Text("—").font(StrandFont.ringScoreSmall).foregroundStyle(StrandPalette.textTertiary)
        }
        .frame(width: diameter, height: diameter)
    }
}

/// A gauge beside its stat rows. Falls back to stacked at accessibility text sizes so nothing truncates.
private struct CoachGaugeLayout<Gauge: View, Rows: View>: View {
    @Environment(\.dynamicTypeSize) private var typeSize
    @ViewBuilder let gauge: () -> Gauge
    @ViewBuilder let rows: () -> Rows

    var body: some View {
        if typeSize.isAccessibilitySize {
            VStack(alignment: .leading, spacing: NoopMetrics.space3) {
                gauge()
                rows()
            }
        } else {
            HStack(alignment: .center, spacing: NoopMetrics.space4) {
                gauge()
                VStack(alignment: .leading, spacing: NoopMetrics.space3) { rows() }
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
    }
}

private enum CoachCardMetrics {
    static let gaugeDiameter: CGFloat = 96
    static let gaugeLineWidth: CGFloat = 7
}

// MARK: - Recovery

private struct CoachRecoveryCard: View {
    let card: LocalCoachCard.Recovery
    @ScaledMetric(relativeTo: .title) private var gauge = CoachCardMetrics.gaugeDiameter

    var body: some View {
        CoachCardChrome(symbol: "heart.fill", title: "Recovery",
                        tint: card.score.map { RecoveryBands.color(for: $0) } ?? StrandPalette.textTertiary,
                        dateLabel: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale) {
            CoachGaugeLayout {
                if let score = card.score {
                    RecoveryRing(score: score, diameter: min(gauge, 132), lineWidth: CoachCardMetrics.gaugeLineWidth,
                                 showsLabel: true, showsWordmark: false, showsHover: false)
                } else {
                    CoachEmptyRing(diameter: min(gauge, 132), lineWidth: CoachCardMetrics.gaugeLineWidth)
                }
            } rows: {
                CoachMetricRow(symbol: "waveform.path.ecg", tint: StrandPalette.metricCyan, label: "HRV",
                               value: LocalCoachCardFormat.whole(card.hrvMs), unit: "ms")
                CoachMetricRow(symbol: "heart.fill", tint: StrandPalette.metricRose, label: "Resting HR",
                               value: LocalCoachCardFormat.whole(card.restingHr), unit: "bpm")
                CoachMetricRow(symbol: "moon.zzz.fill", tint: StrandPalette.sleepAccent, label: "Sleep",
                               value: LocalCoachCardFormat.duration(minutes: card.sleepMinutes))
            }
        }
    }
}

// MARK: - Sleep

private struct CoachSleepCard: View {
    let card: LocalCoachCard.Sleep
    @ScaledMetric(relativeTo: .title) private var bigValue: CGFloat = 34

    private var stages: [(label: String, minutes: Double?, color: Color)] {
        [("Deep", card.deepMinutes, StrandPalette.sleepDeep),
         ("REM", card.remMinutes, StrandPalette.sleepREM),
         ("Light", card.lightMinutes, StrandPalette.sleepLight)]
    }

    var body: some View {
        CoachCardChrome(symbol: "moon.stars.fill", title: "Sleep", tint: StrandPalette.sleepAccent,
                        dateLabel: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale) {
            VStack(alignment: .leading, spacing: NoopMetrics.space3) {
                HStack(alignment: .firstTextBaseline) {
                    Text(LocalCoachCardFormat.duration(minutes: card.totalMinutes))
                        .font(StrandFont.number(bigValue, weight: .bold))
                        .foregroundStyle(card.totalMinutes == nil ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                        .lineLimit(1).minimumScaleFactor(0.7)
                    Spacer(minLength: NoopMetrics.space2)
                    if let efficiency = card.efficiencyPercent {
                        VStack(alignment: .trailing, spacing: 0) {
                            Text(LocalCoachCardFormat.whole(efficiency, unit: "%"))
                                .font(StrandFont.bodyNumber).foregroundStyle(StrandPalette.textPrimary)
                            Text("Efficiency").font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                        }
                    }
                }
                if stages.contains(where: { ($0.minutes ?? 0) > 0 }) {
                    CoachStageBar(stages: stages.map { (minutes: $0.minutes, color: $0.color) })
                }
                HStack(alignment: .top, spacing: NoopMetrics.space2) {
                    ForEach(stages, id: \.label) { stage in
                        HStack(alignment: .top, spacing: 6) {
                            Circle().fill(stage.color).frame(width: 7, height: 7).padding(.top, 4)
                            VStack(alignment: .leading, spacing: 0) {
                                Text(stage.label).font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                                Text(LocalCoachCardFormat.duration(minutes: stage.minutes))
                                    .font(StrandFont.captionNumber)
                                    .foregroundStyle(stage.minutes == nil ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                                    .lineLimit(1).minimumScaleFactor(0.8)
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                    }
                }
                if card.recentNights.count > 1 {
                    VStack(alignment: .leading, spacing: 4) {
                        Text("Last \(card.recentNights.count) recorded nights")
                            .font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                        Sparkline(values: card.recentNights.map { $0.value / 60 }, gradient: StrandPalette.restGradient,
                                  lineWidth: 2, showsArea: true, showsHead: true, showsHover: false)
                            .frame(height: 40).accessibilityHidden(true)
                    }
                }
            }
        }
    }
}

/// Deep / REM / light as proportional capsule segments. Only stages that were recorded are drawn.
private struct CoachStageBar: View {
    let stages: [(minutes: Double?, color: Color)]

    var body: some View {
        let present = stages.compactMap { stage -> (Double, Color)? in
            guard let minutes = stage.minutes, minutes > 0 else { return nil }
            return (minutes, stage.color)
        }
        let total = present.reduce(0) { $0 + $1.0 }
        GeometryReader { proxy in
            let gaps = CGFloat(max(0, present.count - 1)) * 2
            HStack(spacing: 2) {
                ForEach(present.indices, id: \.self) { index in
                    RoundedRectangle(cornerRadius: 3, style: .continuous)
                        .fill(present[index].1)
                        .frame(width: max(3, (proxy.size.width - gaps) * present[index].0 / total))
                }
            }
        }
        .frame(height: 10)
        .clipShape(Capsule(style: .continuous))
        .accessibilityHidden(true)
    }
}

// MARK: - Trend

/// Per-metric number formatting. Effort is stored 0...100 and shown on the user's display scale.
private struct CoachTrendFormat {
    let metricID: String
    let effortScale: EffortScale

    var isEffort: Bool { metricID == "strain" }

    func value(_ stored: Double) -> Double { isEffort ? UnitFormatter.effortValue(stored, scale: effortScale) : stored }

    func text(_ stored: Double?) -> String {
        guard let stored else { return "—" }
        switch metricID {
        case "strain", "sleep": return LocalCoachCardFormat.oneDecimal(value(stored))
        default: return LocalCoachCardFormat.whole(stored)
        }
    }

    func unit(_ payloadUnit: String) -> String { isEffort ? "of \(UnitFormatter.effortScaleMax(effortScale))" : payloadUnit }

    var accent: Color {
        switch metricID {
        case "recovery": return StrandPalette.recoveryHigh
        case "strain": return StrandPalette.strainAccent
        case "sleep": return StrandPalette.sleepAccent
        case "hrv": return StrandPalette.metricCyan
        default: return StrandPalette.metricRose
        }
    }

    var symbol: String {
        switch metricID {
        case "recovery": return "heart.fill"
        case "strain": return "flame.fill"
        case "sleep": return "moon.stars.fill"
        case "hrv": return "waveform.path.ecg"
        default: return "heart.fill"
        }
    }
}

private struct CoachTrendCard: View {
    let card: LocalCoachCard.Trend
    let effortScale: EffortScale
    @ScaledMetric(relativeTo: .title) private var bigValue: CGFloat = 34

    private var format: CoachTrendFormat { CoachTrendFormat(metricID: card.metricID, effortScale: effortScale) }

    private var chartPoints: [TrendPoint] {
        card.points.compactMap { point in
            LocalCoachWindow.date(point.day).map { TrendPoint(date: $0, value: format.value(point.value)) }
        }
    }

    /// Fit the axis to the observed range with headroom, so a steady series is not drawn as a flat line.
    private var domain: ClosedRange<Double> {
        let values = chartPoints.map(\.value)
        guard let low = values.min(), let high = values.max() else { return 0...1 }
        let pad = max((high - low) * 0.2, 0.5)
        return (low - pad)...(high + pad)
    }

    private var gradient: Gradient {
        card.metricID == "recovery" ? StrandPalette.recoveryGradient
            : Gradient(colors: [format.accent.opacity(0.55), format.accent])
    }

    var body: some View {
        CoachCardChrome(symbol: format.symbol, title: "\(card.title) trend", tint: format.accent,
                        dateLabel: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale) {
            VStack(alignment: .leading, spacing: NoopMetrics.space3) {
                HStack(alignment: .firstTextBaseline, spacing: 4) {
                    Text(format.text(card.latest)).font(StrandFont.number(bigValue, weight: .bold))
                        .foregroundStyle(card.latest == nil ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                        .lineLimit(1).minimumScaleFactor(0.7)
                    Text(format.unit(card.unit)).font(StrandFont.caption).foregroundStyle(StrandPalette.textTertiary)
                    Spacer(minLength: NoopMetrics.space2)
                    Text("\(card.points.count) recorded days")
                        .font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                }
                if chartPoints.count > 1 {
                    TrendChart(points: chartPoints, gradient: gradient,
                               valueRange: card.metricID == "recovery" ? 0...100 : domain, showsArea: true,
                               height: 112, showsHover: false,
                               valueFormat: { format.text($0) },
                               accessibilityLabel: "\(card.title) trend", yDomain: domain,
                               xAxisEndPadding: 22)
                        .accessibilityHidden(true)
                }
                HStack(alignment: .top, spacing: NoopMetrics.space2) {
                    CoachTrendStat(label: "Low", value: format.text(card.minimum))
                    CoachTrendStat(label: "Average", value: format.text(card.average))
                    CoachTrendStat(label: "High", value: format.text(card.maximum))
                }
            }
        }
    }
}

private struct CoachTrendStat: View {
    let label: String
    let value: String

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Text(label).font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
            Text(value).font(StrandFont.bodyNumber)
                .foregroundStyle(value == "—" ? StrandPalette.textTertiary : StrandPalette.textPrimary)
                .lineLimit(1).minimumScaleFactor(0.8)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

// MARK: - Effort

private struct CoachEffortCard: View {
    let card: LocalCoachCard.Effort
    let effortScale: EffortScale
    @ScaledMetric(relativeTo: .title) private var gauge = CoachCardMetrics.gaugeDiameter

    var body: some View {
        CoachCardChrome(symbol: "flame.fill", title: "Effort", tint: StrandPalette.strainAccent,
                        dateLabel: LocalCoachCardFormat.dayLabel(card.day), isStale: card.isStale) {
            CoachGaugeLayout {
                if let stored = card.value {
                    StrainGauge(strain: UnitFormatter.effortValue(stored, scale: effortScale), outOf: 21,
                                diameter: min(gauge, 132), lineWidth: CoachCardMetrics.gaugeLineWidth,
                                showsLabel: true, showsHover: false,
                                valueFormat: { _ in UnitFormatter.effortDisplay(stored, scale: effortScale) })
                } else {
                    CoachEmptyRing(diameter: min(gauge, 132), lineWidth: CoachCardMetrics.gaugeLineWidth)
                }
            } rows: {
                CoachMetricRow(symbol: "figure.run", tint: StrandPalette.strainAccent, label: "Workouts",
                               value: card.workoutCount.map(String.init) ?? "—",
                               unit: card.workoutCount == nil ? nil : "in \(card.windowDays) d")
                if let stored = card.value {
                    CoachMetricRow(symbol: "speedometer", tint: StrandPalette.strainAccent, label: "Load",
                                   value: StrainScale.band(UnitFormatter.effortValue(stored, scale: effortScale)).title)
                    Text("Out of \(UnitFormatter.effortScaleMax(effortScale))")
                        .font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                }
            }
        }
    }
}

// MARK: - Workouts

private struct CoachWorkoutsCard: View {
    let card: LocalCoachCard.Workouts
    let effortScale: EffortScale

    /// A list of workouts has no single record date; show the window that was read when it is known.
    private var windowLabel: String? {
        guard let from = card.windowFrom, let through = card.windowThrough else { return nil }
        return LocalCoachCardFormat.windowLabel(from: from, through: through)
    }

    var body: some View {
        CoachCardChrome(symbol: "figure.run", title: "Recent workouts", tint: StrandPalette.strainAccent,
                        dateLabel: windowLabel, isStale: card.isStale) {
            VStack(spacing: 0) {
                ForEach(Array(card.items.enumerated()), id: \.offset) { index, item in
                    if index > 0 {
                        Rectangle().fill(StrandPalette.hairline).frame(height: 1).accessibilityHidden(true)
                    }
                    CoachWorkoutRow(item: item, effortScale: effortScale)
                        .padding(.vertical, NoopMetrics.space2)
                }
            }
        }
    }
}

private struct CoachWorkoutRow: View {
    let item: LocalCoachCard.WorkoutItem
    let effortScale: EffortScale

    var body: some View {
        HStack(spacing: NoopMetrics.space3) {
            Image(systemName: sportSymbol(item.sport)).font(StrandFont.body)
                .foregroundStyle(StrandPalette.strainAccent)
                .frame(width: NoopMetrics.iconCircleDiameter, height: NoopMetrics.iconCircleDiameter)
                .background(StrandPalette.strainAccent.opacity(0.14), in: Circle())
            VStack(alignment: .leading, spacing: 2) {
                Text(item.sport).font(StrandFont.subhead.weight(.semibold))
                    .foregroundStyle(StrandPalette.textPrimary).lineLimit(1)
                Text("\(LocalCoachCardFormat.startLabel(item.startTs)) · \(LocalCoachCardFormat.duration(seconds: item.durationS))")
                    .font(StrandFont.footnote).foregroundStyle(StrandPalette.textSecondary).lineLimit(1)
            }
            Spacer(minLength: NoopMetrics.space1)
            CoachWorkoutFigure(value: LocalCoachCardFormat.whole(item.avgHr), label: "BPM",
                               tint: StrandPalette.textPrimary)
            CoachWorkoutFigure(value: item.effort.map { UnitFormatter.effortDisplay($0, scale: effortScale) } ?? "—",
                               label: "EFFORT", tint: StrandPalette.strainAccent)
        }
    }
}

private struct CoachWorkoutFigure: View {
    let value: String
    let label: String
    let tint: Color

    var body: some View {
        VStack(alignment: .trailing, spacing: 0) {
            Text(value).font(StrandFont.bodyNumber)
                .foregroundStyle(value == "—" ? StrandPalette.textTertiary : tint).lineLimit(1)
            Text(label).font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
        }
        .frame(minWidth: 40, alignment: .trailing)
    }
}

// MARK: - Stats

private struct CoachStatsCard: View {
    let card: LocalCoachCard.Stats
    @ScaledMetric(relativeTo: .title3) private var valueSize: CGFloat = 20

    private var symbol: String {
        card.title == "Recorded nutrition" ? "fork.knife" : "clock.arrow.circlepath"
    }

    var body: some View {
        CoachCardChrome(symbol: symbol, title: card.title, tint: StrandPalette.accent,
                        dateLabel: card.day.map { LocalCoachCardFormat.dayLabel($0) }, isStale: card.isStale) {
            // One shared value size for every column: the largest that fits on one line, else a smaller
            // shared size that may wrap to two lines. Columns never shrink independently.
            ViewThatFits(in: .horizontal) {
                columns(size: valueSize, lines: 1)
                columns(size: valueSize * 0.85, lines: 1)
                columns(size: valueSize * 0.7, lines: 2)
            }
        }
    }

    private func columns(size: CGFloat, lines: Int) -> some View {
        HStack(alignment: .top, spacing: 0) {
            ForEach(Array(card.items.prefix(3).enumerated()), id: \.offset) { index, item in
                if index > 0 {
                    Rectangle().fill(StrandPalette.hairline).frame(width: 1, height: 34)
                        .accessibilityHidden(true)
                }
                VStack(alignment: .leading, spacing: 4) {
                    Text(item.label).font(StrandFont.micro).foregroundStyle(StrandPalette.textTertiary)
                        .lineLimit(1)
                    Text(LocalCoachCardFormat.displayValue(item.value))
                        .font(StrandFont.number(size, weight: .semibold))
                        .foregroundStyle(StrandPalette.textPrimary)
                        .lineLimit(lines)
                        // One-line sizes report their full width, so ViewThatFits moves to the next
                        // shared size instead of truncating a single column.
                        .fixedSize(horizontal: lines == 1, vertical: true)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.leading, index == 0 ? 0 : NoopMetrics.space3)
                .padding(.trailing, index == min(card.items.count, 3) - 1 ? 0 : NoopMetrics.space3)
            }
        }
    }
}
#endif
